with remaining_keys as (select channel, promo_code from promotions intersect all select channel, promo_code from promotions where promo_code = 'WELCOME5'), reconciled as (select s.* from promotions s join remaining_keys k on s.channel = k.channel and s.promo_code = k.promo_code) select date_trunc('quarter', ends_on) as quarter_start, channel, promo_code, count(distinct id) as distinct_ids, sum(case when channel = 'mobile' then discount_pct else 0 end) as mobile_discount_pct, stddev_samp(discount_pct) as discount_pct_stddev from reconciled group by quarter_start, channel, promo_code;
